create table if not exists accounts (id text primary key, name text not null default 'My Aviary', created_at timestamptz not null default now());
create table if not exists auth_links (auth_id text primary key, account_id text not null, user_id text, email text not null default '', created_at timestamptz not null default now());
grant birdbox_app to current_user;
grant usage on schema public to birdbox_app;
grant select on species, species_names to birdbox_app;
grant usage on all sequences in schema public to birdbox_app;

-- birds
alter table birds add column if not exists account_id text;
alter table birds add column if not exists is_demo boolean not null default false;
update birds set account_id = 'legacy' where account_id is null;
alter table birds alter column account_id set default nullif(current_setting('app.account_id', true), '');
alter table birds alter column account_id set not null;
alter table birds drop constraint if exists birds_pkey cascade;
alter table birds add primary key (account_id, id);
alter table birds enable row level security;
alter table birds force row level security;
drop policy if exists tenant_isolation on birds;
create policy tenant_isolation on birds using (account_id = nullif(current_setting('app.account_id', true), '')) with check (account_id = nullif(current_setting('app.account_id', true), ''));
drop policy if exists demo_read on birds;
create policy demo_read on birds for select using (account_id = 'demo' and current_setting('app.loading_demo', true) = 'on');
grant select, insert, update, delete on birds to birdbox_app;

